// تشغيل نغمة تنبيه صوتي واضحة عند اكتشاف طلب جديد
try {
  const doc = wwLib.getFrontDocument();
  const win = doc ? doc.defaultView : null;
  const AudioCtx = win ? (win.AudioContext || win.webkitAudioContext) : null;
  if (!AudioCtx) return false;
  const ctx = new AudioCtx();
  const playTone = (freq, startTime, duration) => {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, startTime);
    gain.gain.setValueAtTime(0.01, startTime);
    gain.gain.exponentialRampToValueAtTime(0.4, startTime + 0.03);
    gain.gain.exponentialRampToValueAtTime(0.001, startTime + duration);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(startTime);
    osc.stop(startTime + duration);
  };
  const now = ctx.currentTime;
  playTone(587.33, now, 0.18);
  playTone(880.00, now + 0.18, 0.22);
  playTone(1174.66, now + 0.40, 0.45);
  return true;
} catch (e) {
  return false;
}

